mapper.select:
SELECT a.`QUESTION_ID_1` AS QUESTION_ID, a.`QUESTION_DSCR_1` AS QUESTION_DSCR FROM `inspection`.`inspection_question_ledger` a JOIN `inspection`.`inspection_task` c ON a.TASK_ID = c.INSPECTION_TASK_ID WHERE 1=1
AND c.`INSPECTION_PLAN_ID` = #{params.INSPECTION_PLAN_ID}
GROUP BY a.`QUESTION_ID_1`

SELECT a.UUID, NAME, GUOKU_ID, GUOKU_DSCR, SEX, ( SELECT ENUM_DSCR FROM enumset.cm_guoku_enumeration WHERE ENUM_TYPE_ID = 5 AND ENUM_ID = SEX ) AS SEX_DSCR, BIRTHDAY, AGE, NATION, ( SELECT ENUM_DSCR FROM enumset.cm_guoku_enumeration WHERE ENUM_TYPE_ID = 2 AND ENUM_ID = NATION ) AS NATION_DSCR, POLITICS, ( SELECT ENUM_DSCR FROM enumset.cm_guoku_enumeration WHERE ENUM_TYPE_ID = 10 AND ENUM_ID = POLITICS ) AS POLITICS_DSCR, MAJOR, EDUCATION, ( SELECT ENUM_DSCR FROM enumset.cm_guoku_enumeration WHERE ENUM_TYPE_ID = 1 AND ENUM_ID = EDUCATION ) AS EDUCATION_DSCR, DUTIES, ( SELECT ENUM_DSCR FROM enumset.cm_guoku_enumeration WHERE ENUM_TYPE_ID = 4 AND ENUM_ID = DUTIES ) AS DUTIES_DSCR, ( SELECT ENUM_ID FROM enumset.cm_guoku_enumeration WHERE ENUM_TYPE_ID = 4 AND ENUM_ID = DUTIES ) AS DUTIES_ORDER, CUR_POSITION, PHONE, WORK_LIFE, EXPERTISE, ( SELECT ENUM_DSCR FROM enumset.cm_guoku_enumeration WHERE ENUM_TYPE_ID = 3 AND ENUM_ID = EXPERTISE ) AS EXPERTISE_DSCR, TITLE, LAWCERT, CASE WHEN LAWCERT = '0' THEN '是' ELSE '否' END AS LAWCERT_DSCR, LAWCERT_NO, CHECK_NO, CHIEF, CASE WHEN CHIEF = '0' THEN '是' ELSE '否' END AS CHIEF_DSCR, MEMO, STATE, LAST_TIME, LAST_USER FROM inspection.cm_guoku_talentpool a WHERE 1 = 1
AND NAME like '%${params.NAME}%'
AND GUOKU_ID = #{params.GUOKU_ID}
AND GUOKU_DSCR like '%${params.GUOKU_DSCR}%'
AND SEX = #{params.SEX}
AND NATION = #{params.NATION}
AND DUTIES = #{params.DUTIES}
AND PHONE like '%${params.PHONE}%'
AND EXPERTISE LIKE '%${item}%'
AND STATE = #{params.STATE}
AND EDUCATION = #{params.EDUCATION}
AND BIRTHDAY = #{params.BIRTHDAY}
AND AGE >= #{params.START_AGE}
AND AGE <= #{params.END_AGE}
AND LAWCERT = #{params.LAWCERT}
AND TITLE = #{params.TITLE}
ORDER BY a.GUOKU_ID, CAST(DUTIES_ORDER AS SIGNED)

SELECT * FROM inspection.inspection_plan a WHERE 1 = 1
AND a.INSPECTION_PLAN_ID != #{params.INSPECTION_PLAN_ID}
AND a.INSPECTION_PLAN_NAME = #{params.INSPECTION_PLAN_NAME}
